;(function(){try{
  /*onk-hash-namen*/ /* Adressen van de Gemeenschap: nooit meer '#feed' tonen. Artikelen: #artikelen / #artikel/<naam> (Engels #articles / #article/<naam>). Oude '#feed...' links blijven werken en worden bij het openen omgezet. */
  function en(){try{return (localStorage.getItem('bible-locale')||'').toLowerCase().indexOf('en')===0;}catch(e){return false;}}
  window.OnkAH=function(slug){return slug==null||slug===''?(en()?'#articles':'#artikelen'):(en()?'#article/':'#artikel/')+slug;};
  var HNT={topic:['bericht','post'],members:['leden','members'],member:['lid','member'],messages:['postvak','inbox'],settings:['instellingen','settings'],following:['volgend','following'],saved:['opgeslagen','saved']};
  window.OnkHN=function(k,arg){var n=HNT[k]||['berichten','posts'];return '#'+n[en()?1:0]+(arg?'/'+arg:'');};
  /* nieuwe hashnamen terug naar de oude interne schrijfwijze voor de oude lijstcode: #bericht/ID -> topic/ID enz. */
  var LEG={bericht:'topic',post:'topic',lid:'member',member:'member',leden:'members',members:'members',postvak:'messages',inbox:'messages',instellingen:'settings',settings:'settings',volgend:'following',following:'following',opgeslagen:'saved',saved:'saved',artikelen:'articles',articles:'articles',artikel:'article',article:'article',berichten:'',posts:''};
  window.OnkLegacyH=function(h){var x=String(h||'').replace(/^#?(?:feed\/?)?/,'');var m=/^([a-z]+)(\/.*)?$/i.exec(x);if(m&&Object.prototype.hasOwnProperty.call(LEG,m[1].toLowerCase())){return LEG[m[1].toLowerCase()]+(m[2]||'');}return x;};
  window.OnkH0=function(){return en()?'posts':'berichten';};
  window.OnkIsArt=function(h){return /^#(?:feed\/)?(?:article|artikel)/i.test(String(h||''));};
  window.OnkIsComm=function(h){h=String(h||'');return /^#feed(\/|$)/.test(h)||window.OnkIsArt(h)||/^#(?:vandaag|today|berichten|posts|activiteiten|activity|leden|members|lid|member|postvak|inbox|bericht|post|volgend|following|opgeslagen|saved|kanalen|channels|kanaal|channel|nieuwkanaal|newchannel)(\/|$)/i.test(h);};
  function omzetten(){
    var h=location.hash||'',m=/^#feed\/(article|articles)(?:\/(.*))?$/.exec(h);
    if(m){var nh=window.OnkAH(m[1]==='article'?m[2]||'':'');try{history.replaceState(history.state,'',location.pathname+location.search+nh);}catch(e){}}
  }
  omzetten();window.addEventListener('hashchange',omzetten);
}catch(err){}})();

;(function(){try{
  /*onk-onderwerpen-naar-zoeken*/ /* De lijst met alle onderwerpen is de zoekpagina in de onderwerpenstand (zelfde stijl en filters). Een onderwerp zelf (?onderwerp= of ?topic=) blijft in de app. Zoekmachines worden niet doorgestuurd. */
  if(/bot|crawl|spider|slurp|lighthouse/i.test(navigator.userAgent||'')||navigator.webdriver)return;
  var done='',armed=!/[?&](onderwerp|topic)=/.test(location.search);
  function check(){
    var p=location.pathname,m=/^(.*\/)(?:onderwerpen|topics)\/?$/i.exec(p);
    if(!m||/[?&]norx=1/.test(location.search)||sessionStorage.getItem('onk-norx'))return;
    /* alleen doorsturen als de oude lijst echt in beeld is (kop 'Bijbelse onderwerpen' / 'Bible Topics'); een geopend onderwerp blijft in de app */
    var hs=document.querySelectorAll('h1'),lijst=false;
    for(var i=0;i<hs.length;i++){if(/^(Bible Topics|Bijbelse onderwerpen)$/i.test((hs[i].textContent||'').trim())){lijst=true;break;}}
    if(!lijst)return;
    /* een geopend onderwerp heeft een terugknop '← All topics' / '← Alle onderwerpen' en blijft in de app */
    if(/\u2190\s*(All topics|Alle onderwerpen)/i.test(document.body.innerText||'')){armed=true;return;}
    if(!armed)return;
    var target=m[1]+'zoeken/?t=o';
    if(done===target&&Date.now()-(window.__onkTopT||0)<3000)return;done=target;window.__onkTopT=Date.now();
    location.replace(target);
  }
  check();setInterval(check,300);
}catch(err){}})();
